import React, { useState } from "react";
import axios from "axios";

function ATSPanel({ data, jobDesc, setJobDesc }) {
  const [score, setScore] = useState(null);
  const [keywords, setKeywords] = useState([]);
  const [loading, setLoading] = useState(false);

  const analyze = async () => {
    if (!jobDesc || !data.skills) return;

    try {
      setLoading(true);

      const res = await axios.post("http://localhost:5000/api/analyze", {
        jobDesc,
        skills: data.skills
          .split(",")
          .map((s) => s.trim().toLowerCase()),
      });

      setScore(res.data.score);
      setKeywords(res.data.keywords);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4">

      {/* Job Description */}
      <textarea
        className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-green-400"
        placeholder="Paste Job Description here..."
        rows="5"
        value={jobDesc}
        onChange={(e) => setJobDesc(e.target.value)}
      />

      {/* Button */}
      <button
        onClick={analyze}
        className="w-full bg-green-500 hover:bg-green-600 text-white py-2 rounded-lg font-medium transition"
      >
        {loading ? "Analyzing..." : "Analyze Resume"}
      </button>

      {/* Score Section */}
      {score !== null && (
        <div className="mt-4">
          <p className="font-semibold text-gray-700 mb-1">
            ATS Score
          </p>

          <div className="w-full bg-gray-200 rounded-full h-3">
            <div
              className="bg-green-500 h-3 rounded-full transition-all duration-500"
              style={{ width: `${score}%` }}
            ></div>
          </div>

          <p className="text-sm text-gray-600 mt-1">
            {score}% match
          </p>
        </div>
      )}

      {/* Keywords */}
      {keywords.length > 0 && (
        <div>
          <p className="font-semibold text-gray-700 mb-2">
            Extracted Keywords
          </p>

          <div className="flex flex-wrap gap-2">
            {keywords.map((word, index) => (
              <span
                key={index}
                className="bg-blue-100 text-blue-700 px-2 py-1 rounded-md text-sm"
              >
                {word}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default ATSPanel;
